  async selectOptimalNodes(availableNodes, targetSize, optimizationTarget) {
    const nodeScores = new Map();

    // Score nodes based on optimization target
    for (const node of availableNodes) {
      let score = 0;

      if (optimizationTarget === 'THROUGHPUT') {
