  async execute(operation, fallback = null) {
    this.metrics.totalRequests++;

    // Check circuit state
    if (this.state === 'OPEN') {
      if (this.shouldAttemptReset()) {
        this.state = 'HALF_OPEN';
        this.successCount = 0;
        this.metrics.circuitHalfOpenEvents++;
