            memoryEfficiency: benchmarkResult.memoryBandwidth / this.hardwareProfile.memoryBandwidth,
            occupancyEfficiency: benchmarkResult.occupancy,
            overallEfficiency: (actualThroughput / theoreticalPeak) * 0.4 + 
                             (benchmarkResult.memoryBandwidth / this.hardwareProfile.memoryBandwidth) * 0.4 +
                             benchmarkResult.occupancy * 0.2
        };
    }

    identifyPerformanceGaps(benchmarkResults) {
        const baseline = benchmarkResults.find(r => r.configuration.name === 'baseline');
        const maxOptimized = benchmarkResults.find(r => r.configuration.name === 'max_optimization');

        const gaps = [];

        if (maxOptimized.efficiency.computeEfficiency < 0.7) {
            gaps.push({
                type: 'compute_underutilization',
                severity: 'high',
                description: 'Compute units are underutilized',
                potentialGain: (0.7 - maxOptimized.efficiency.computeEfficiency) * 100 + '%'
            });
        }

        if (maxOptimized.efficiency.memoryEfficiency < 0.6) {
