// bank_conflict_elimination.cu - Advanced shared memory optimization
__global__ void optimized_reduction(
    float* input, float* output, int n
) {
    // Pad shared memory to avoid bank conflicts
    __shared__ float sdata[256 + 8]; // 8 extra elements for padding

    int tid = threadIdx.x;
    int gid = blockIdx.x * blockDim.x + threadIdx.x;

    // Load data with proper stride to avoid conflicts
    sdata[tid] = (gid < n) ? input[gid] : 0.0f;
    __syncthreads();

    // Optimized reduction loop with conflict-free addressing
    for (int s = blockDim.x / 2; s > 32; s >>= 1) {
        if (tid < s) {
            // Use XOR addressing to avoid bank conflicts
            int conflict_free_tid = tid ^ (tid >> 5);
            sdata[conflict_free_tid] += sdata[conflict_free_tid + s];
        }
        __syncthreads();
    }

    // Final warp reduction (no synchronization needed)
    if (tid < 32) {
        volatile float* vmem = sdata;
        vmem[tid] += vmem[tid + 32];
        vmem[tid] += vmem[tid + 16];
        vmem[tid] += vmem[tid + 8];
        vmem[tid] += vmem[tid + 4];
        vmem[tid] += vmem[tid + 2];
        vmem[tid] += vmem[tid + 1];
    }

    if (tid == 0) {
        output[blockIdx.x] = sdata[0];
    }
}
