// Dynamic workgroup size optimization
class WorkgroupOptimizer {
    constructor() {
        this.optimalSizes = new Map();
        this.performanceHistory = [];
    }

    async findOptimalWorkgroupSize(kernelCode, problemSize) {
        const cacheKey = `${this.hashKernel(kernelCode)}_${problemSize}`;

        if (this.optimalSizes.has(cacheKey)) {
            return this.optimalSizes.get(cacheKey);
        }

        const candidates = [
            [64, 1, 1], [128, 1, 1], [256, 1, 1], [512, 1, 1],
            [8, 8, 1], [16, 16, 1], [32, 32, 1],
            [8, 8, 4], [16, 8, 2], [32, 4, 2]
        ];

        let bestPerformance = 0;
        let optimalSize = [256, 1, 1];

        for (const size of candidates) {
            try {
                const performance = await this.benchmarkWorkgroupSize(
                    kernelCode, size, problemSize
                );

                if (performance.throughput > bestPerformance) {
                    bestPerformance = performance.throughput;
                    optimalSize = size;
                }
            } catch (error) {
                // Size not supported, skip
                continue;
            }
        }

        this.optimalSizes.set(cacheKey, optimalSize);
        return optimalSize;
    }

    async benchmarkWorkgroupSize(kernelCode, workgroupSize, problemSize) {
        const transpiled = await transpileCuda(kernelCode, {
            target: 'webgpu',
            optimize: true,
            workgroupSize: workgroupSize
        });

        const kernel = await createWebGPUKernel(device, transpiled.code, {
            workgroupSize: workgroupSize,
            enableProfiling: true
        });

        // Benchmark with representative data
        const testData = this.generateTestData(problemSize);
        const iterations = 20;
        const times = [];

        for (let i = 0; i < iterations; i++) {
            await kernel.writeBuffer(0, testData);

            const start = performance.now();
            await kernel.dispatch(
                Math.ceil(problemSize / workgroupSize[0]),
                Math.ceil(1 / workgroupSize[1]),
                Math.ceil(1 / workgroupSize[2])
            );
            times.push(performance.now() - start);
        }

        const avgTime = times.reduce((a, b) => a + b) / times.length;
        const throughput = problemSize / (avgTime / 1000) / (1000 * 1000); // Mops/s

        return { throughput, avgTime, workgroupSize };
    }
}

