        const width = this.canvas.width;
        const height = this.canvas.height;

        // Clear canvas
        ctx.fillStyle = '#333';
        ctx.fillRect(0, 0, width, height);

        if (this.dataPoints.length < 2) return;

        // Draw grid
        ctx.strokeStyle = '#555';
        ctx.lineWidth = 1;
        for (let i = 0; i < 10; i++) {
            const y = (height / 10) * i;
            ctx.beginPath();
            ctx.moveTo(0, y);
            ctx.lineTo(width, y);
            ctx.stroke();
        }

        // Draw execution time line
        this.drawLine(
            this.dataPoints.map(p => p.executionTime),
            '#ff6b6b',
            100 // max scale
        );

        // Draw throughput line
        this.drawLine(
            this.dataPoints.map(p => p.throughput),
            '#4ecdc4',
            1000 // max scale
        );

        // Draw temperature line
        this.drawLine(
            this.dataPoints.map(p => p.temperature),
            '#45b7d1',
            100 // max scale
        );

        // Draw legend
        this.drawLegend();
    }

    drawLine(values, color, maxValue) {
        const ctx = this.ctx;
        const width = this.canvas.width;
        const height = this.canvas.height;

        ctx.strokeStyle = color;
        ctx.lineWidth = 2;
        ctx.beginPath();

        for (let i = 0; i < values.length; i++) {
            const x = (width / (this.maxDataPoints - 1)) * i;
            const y = height - (values[i] / maxValue) * height;

            if (i === 0) {
                ctx.moveTo(x, y);
            } else {
                ctx.lineTo(x, y);
            }
        }

        ctx.stroke();
    }

    drawLegend() {
        const ctx = this.ctx;

        ctx.fillStyle = 'white';
        ctx.font = '12px monospace';

        ctx.fillText('Exec Time (ms)', 10, 20);
        ctx.fillStyle = '#ff6b6b';
        ctx.fillRect(110, 12, 10, 10);

