        ctx.fillStyle = '#4ecdc4';
        ctx.fillRect(150, 32, 10, 10);

        ctx.fillStyle = 'white';
        ctx.fillText('Temperature (°C)', 10, 60);
        ctx.fillStyle = '#45b7d1';
        ctx.fillRect(130, 52, 10, 10);
    }
}

