use polars::prelude::*;

// Create forecast data
let forecast_data = df! {
    "unique_id" => vec!["A", "A", "B", "B"],
    "ds" => vec![3, 4, 3, 4],
    "LSTM" => vec![12.5, 13.2, 26.1, 27.3],
    "NBEATS" => vec![12.1, 13.0, 25.8, 26.9],
}?;

let forecast_df = ForecastDataFrame::new(
    forecast_data,
    vec!["LSTM".to_string(), "NBEATS".to_string()],
