 Breaker Pattern

**Circuit Breaker Implementation**:
```rust
use std::sync::{Arc, Mutex};
use std::time::{Duration, Instant};

#[derive(Clone)]
pub struct CircuitBreaker {
    state: Arc<Mutex<CircuitState>>,
    failure_threshold: usize,
    recovery_timeout: Duration,
}

#[derive(Debug)]
enum CircuitState {
    Closed { failure_count: usize },
    Open { last_failure: Instant },
    HalfOpen,
}

impl CircuitBreaker {
    pub fn new(failure_threshold: usize, recovery_timeout: Duration) -> Self {
        Self {
            state: Arc::new(Mutex::new(CircuitState::Closed { failure_count: 0 })),
            failure_threshold,
            recovery_timeout,
        }
    }

    pub async fn call<F, R, E>(&self, f: F) -> Result<R, CircuitBreakerError>
    where
        F: FnOnce() -> Result<R, E>,
        E: std::error::Error,
    {
        // Check if circuit is open
        if self.is_open()? {
            return Err(CircuitBreakerError::Open);
        }

        // Execute function
        match f() {
            Ok(result) => {
                self.on_success();
                Ok(result)
            }
            Err(e) => {
                self.on_failure();
                Err(CircuitBreakerError::Failure(Box::new(e)))
            }
        }
    }

    fn is_open(&self) -> Result<bool, CircuitBreakerError> {
        let mut state = self.state.lock().unwrap();

        match *state {
            CircuitState::Open { last_failure } => {
                if last_failure.elapsed() > self.recovery_timeout {
                    *state = CircuitState::HalfOpen;
                    Ok(false)
                } else {
                    Ok(true)
                }
            }
            _ => Ok(false),
        }
    }

    fn on_success(&self) {
        let mut state = self.state.lock().unwrap();
        *state = CircuitState::Closed { failure_count: 0 };
    }

    fn on_failure(&self) {
        let mut state = self.state.lock().unwrap();

        match *state {
            CircuitState::Closed { failure_count } => {
                let new_count = failure_count + 1;
                if new_count >= self.failure_threshold {
                    *state = CircuitState::Open {
                        last_failure: Instant::now(),
                    };
                } else {
                    *state = CircuitState::Closed {
                        failure_count: new_count,
                    };
                }
            }
            CircuitState::HalfOpen => {
                *state = CircuitState::Open {
                    last_failure: Instant::now(),
                };
            }
            _ => {}
        }
    }
}

#[derive(Debug, thiserror::Error)]
pub enum CircuitBreakerError {
    #[error("Circuit breaker is open")]
    Open,
    #[error("Function call failed: {0}")]
    Failure(Box<dyn std::error::Error + Send + Sync>),
}
