```rust
let df = df.with_columns([
    col("ds").map(
        |s| {
            s.str()?
                .into_iter()
                .map(|opt_s| {
                    opt_s.and_then(|s| {
                        chrono::NaiveDateTime::parse_from_str(s, "%Y-%m-%d %H:%M:%S")
                            .ok()
                            .map(|dt| dt.timestamp_nanos())
                    })
                })
                .collect::<Int64Chunked>()
                .into_series()
        },
        GetOutput::from_type(DataType::Int64),
    ).cast(DataType::Datetime(TimeUnit::Nanoseconds, None))
]);
