use polars::prelude::*;

fn process_large_file(path: &str) -> PolarsResult<()> {
    let mut reader = CsvReader::from_path(path)?
        .infer_schema(Some(1000))
        .has_header(true)
        .batch_size(10000);

    while let Some(batch) = reader.next_batch()? {
        // Process each batch
        process_batch(batch)?;
    }

    Ok(())
}
```

