        .with_model("tft", Box::new(tft))
        .with_ensemble(WeightedEnsemble::new(vec![0.3, 0.4, 0.3]))
        .build()?;

    // Train ensemble
    ensemble.fit(&train_data).await?;

    // Generate ensemble forecasts
    let forecasts = ensemble.predict().await?;

    Ok(())
