```rust
#[async_trait]
pub trait Agent: Send + Sync {
    type Input: Send;
    type Output: Send;
    type Error: fmt::Debug + Send;

    // Required methods
    async fn process(&mut self, input: Self::Input) -> Result<Self::Output, Self::Error>;
