class BroadcastProtocol {
  private messageCache: LRUCache<string, SwarmMessage>;

  broadcast(message: SwarmMessage): void {
    // Deduplication
    const hash = this.hashMessage(message);
    if (this.messageCache.has(hash)) {
      return; // Already broadcast
