    // Efficient distribution
    const agents = this.swarm.getActiveAgents();
    const batches = this.batchAgents(agents, 10);

    for (const batch of batches) {
      this.sendBatch(batch, message);
    }

    this.messageCache.set(hash, message);
  }
}
