        let config: TrainingConfig = serde_wasm_bindgen::from_value(config)
            .map_err(|e| JsValue::from_str(&format!("Invalid training config: {}", e)))?;

        let algorithm = match config.algorithm.to_lowercase().as_str() {
            "incremental_backprop" => {
