                trainer.train_epoch(&mut network.inner, &training_data)
                    .map_err(|e| JsValue::from_str(&format!("Training error: {}", e)))?
            },
            TrainingAlgorithmWasm::Sarprop(trainer) => {
                trainer.train_epoch(&mut network.inner, &training_data)
