            const sizeReduction = ((originalSize - optimizedSize) / originalSize * 100).toFixed(1);

            results[path.basename(wasmFile)] = {
                success: true,
                originalSize,
                optimizedSize,
                sizeReduction: `${sizeReduction}%`,
                optimizationTime
            };

            console.log(`  ⚡ ${path.basename(wasmFile)}: ${sizeReduction}% smaller`);
        } catch (error) {
            results[path.basename(wasmFile)] = {
                success: false,
                error: error.message
            };
        }
    }

    return results;
