            _ => ExecutionPlan::Hierarchical {
                coordinator: agents[0].clone(),
                workers: agents[1..].to_vec(),
                coordination_overhead: 0.2,
                estimated_time: task.estimated_complexity * 700.0, // 30% faster but with coordination overhead
            },
        };

