}

#[cfg(feature = "python")]
use pyo3::prelude::*;

#[cfg(feature = "python")]
#[pymodule]
fn opencv_sdk(_py: Python, m: &PyModule) -> PyResult<()> {
    m.add_function(wrap_pyfunction!(py_init, m)?)?;
    m.add_class::<PyMat>()?;
    Ok(())
}

#[cfg(feature = "python")]
#[pyfunction]
fn py_init() -> PyResult<()> {
    init().map_err(|e| pyo3::exceptions::PyRuntimeError::new_err(e.to_string()))
}

